const SPANISH_EXTENDED_VOCAB = VOCAB_DB.map((item, idx) => {
  const [word, pron] = SPANISH_EXTENDED_WORDS[idx];
  return {
    id: `esx${String(idx + 1).padStart(3, '0')}`,
    lv: item.lv,
    word,
    pron,
    jp: item.jp,
    ex: `${word} (${pron}) = ${item.jp}`,
  };
});

function grammarItems(code, rows) {
  return rows.map(([lv, q, choices, ans, exp], idx) => ({
    id: `${code}g${String(idx + 1).padStart(3, '0')}`,
    lv, q, choices, ans, exp,
  }));
}

