function appendGrammarItems(code, rows) {
  const base = MULTI_GRAMMAR_DB[code] || [];
  base.push(...rows.map(([lv, q, choices, ans, exp], idx) => ({
    id: `${code}g${String(base.length + idx + 1).padStart(3, '0')}`,
    lv, q, choices, ans, exp,
  })));
  MULTI_GRAMMAR_DB[code] = base;
}

