export const MULTI_PHRASE_DB = Object.fromEntries(
  Object.entries(PHRASE_TEXT_BY_LANGUAGE).map(([code, phrases]) => [
    code,
    phrases.map((phrase, idx) => {
      const [situation, lv, en, jp] = PHRASE_MEANINGS[idx];
      const pron = PHRASE_PRON_BY_LANGUAGE[code]?.[idx];
      return {
        id: `${code}ph${String(idx + 1).padStart(3, '0')}`,
        situation, lv, phrase,
        pron: pron || undefined,
        jp,
        en,
      };
    }),
  ]),
);

/* ══════════════════════════════════════════════════
   文化・名産品・歴史クイズ（せかいマップの地域ゾーンで出会う問題）
   学習中の言語圏について、日本語で出題する4択トリビア
   まずは主要言語から着手し、他言語は今後のバッチで拡充する
══════════════════════════════════════════════════ */
function cultureItems(code, rows) {
  return rows.map(([lv, q, choices, ans, exp], idx) => ({
    id: `${code}c${String(idx + 1).padStart(3, '0')}`,
    lv, q, choices, ans, exp,
  }));
}

